            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            # Fill the hollow interior of the rectangular frame.
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # The top edge has a one-cell opening. Project from it toward
            # the side with the longer remaining top rim.
            gaps = [x for x in range(c0, c1 + 1) if grid[r0][x] == 0]
            if r0 > 0 and len(gaps) == 1:
                x = gaps[0]
                left_rim = sum(grid[r0][z] == 5 for z in range(c0, x))
                right_rim = sum(grid[r0][z] == 5 for z in range(x + 1, c1 + 1))
                direction = -1 if left_rim >= right_rim else 1
                z = x
                while 0 <= z < w:
                    out[r0 - 1][z] = 2
                    z += direction
    return out
